import React, { useState, useEffect, useRef } from 'react';
import ChatHistory from './ChatHistory';
import TextInput from './TextInput';
import VoiceInput from './VoiceInput';
import DocumentUpload from './DocumentUpload';
// import { sendChatMessage, uploadVoiceMessage, uploadDocument } from '../../../services/api'; // Placeholder

// Placeholder ChatInterface component
const ChatInterface = ({ processId }) => {
  const [messages, setMessages] = useState([]);
  const [isSending, setIsSending] = useState(false);
  // const chatHistoryRef = useRef(null); // For auto-scrolling

  // Placeholder: Fetch initial chat history for the processId
  useEffect(() => {
    // Simulating fetching initial messages
    // In a real app, you'd call an API: fetchChatHistory(processId)
    // setMessages(initialMessagesFromServer);
    console.log(`ChatInterface mounted for processId: ${processId}. Fetch history here.`);
  }, [processId]);

  // Auto-scroll to bottom - implement later if needed
  // useEffect(() => {
  //   if (chatHistoryRef.current) {
  //     chatHistoryRef.current.scrollTop = chatHistoryRef.current.scrollHeight;
  //   }
  // }, [messages]);

  const handleSendMessage = async (messageData) => {
    setIsSending(true);
    const userMessage = {
      id: `user-${Date.now()}`,
      text: messageData.type === 'text' ? messageData.content : `Sent ${messageData.type}: ${messageData.name || 'audio'}`,
      type: 'user',
      timestamp: new Date()
    };
    setMessages(prev => [...prev, userMessage]);

    try {
      let aiResponseText = 'Placeholder AI response.';
      // switch (messageData.type) {
      //   case 'text':
      //     aiResponseText = await sendChatMessage(processId, messageData.content);
      //     break;
      //   case 'voice':
      //     aiResponseText = await uploadVoiceMessage(processId, messageData.content); // content is Blob
      //     break;
      //   case 'document':
      //     aiResponseText = await uploadDocument(processId, messageData.content); // content is File
      //     break;
      //   default:
      //     throw new Error('Unknown message type');
      // }

      // Simulate AI response delay
      await new Promise(resolve => setTimeout(resolve, 1000));

      const aiMessage = {
        id: `ai-${Date.now()}`,
        text: `AI: Thanks for the ${messageData.type}. ${aiResponseText}`,
        type: 'ai',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, aiMessage]);

    } catch (error) {
      console.error("Error sending message or getting AI response:", error);
      const errorMessage = {
        id: `err-${Date.now()}`,
        text: `Error: Could not get AI response. ${error.message}`,
        type: 'ai', // Or a special 'error' type
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsSending(false);
    }
  };

  const interfaceStyle = {
    border: '1px solid #e0e0e0',
    padding: 'var(--spacing-unit, 16px)',
    height: 'calc(100% - 32px)', // Fill panel, account for padding
    display: 'flex',
    flexDirection: 'column',
    backgroundColor: '#fff',
    boxSizing: 'border-box'
  };

  const inputSectionStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: 'var(--spacing-unit, 16px)',
    marginTop: 'auto', // Pushes input to the bottom
    paddingTop: 'var(--spacing-unit, 16px)' // Space above inputs
  };

  const inputControlsStyle = {
    display: 'flex',
    gap: 'var(--spacing-unit, 16px)',
    alignItems: 'center',
    flexWrap: 'wrap'
  };

  return (
    <div style={interfaceStyle}>
      <h4 style={{ marginTop: 0, marginBottom: 'var(--spacing-unit, 16px)' }}>
        Chat with AI (Process ID: {processId})
      </h4>
      <ChatHistory messages={messages} /> {/* Pass messages state */}
      <div style={inputSectionStyle}>
        <TextInput onSendMessage={handleSendMessage} />
        <div style={inputControlsStyle}>
          <VoiceInput onSendVoice={handleSendMessage} />
          <DocumentUpload onSendDocument={handleSendMessage} />
        </div>
        {isSending && <p style={{ fontSize: '12px', textAlign:'center' }}><i>Communicating with AI...</i></p>}
      </div>
    </div>
  );
};

export default ChatInterface;
